return {
  ...$json,
  environment: {
    profile: 'controlled',
    runtime: 'javascript-vm',
    timezone: 'UTC',
    locale: 'C',
    architecture: 'portable',
    dependencyLock: 'sciforge-create-loop@1.0.0'
  }
};

const baselineScore = Number($json.baselineScore ?? 100);
const observedScore = Number($json.observedScore ?? baselineScore);
const tolerance = Number($json.tolerance ?? 0.1);
return {
  ...$json,
  baselineScore,
  observedScore,
  tolerance,
  parameters: {
    randomSeed: Number($json.randomSeed ?? 20260805),
    precision: Number($json.precision ?? 2),
    comparisonMode: String($json.comparisonMode ?? 'tolerance'),
    tolerance
  },
  codeSnapshot: {
    id: 'code:dag-v3-difference-v2',
    language: 'javascript',
    version: '2.0.0',
    algorithm: 'absolute-difference-v1',
    contentDigest: 'sha256:79cbf430cbf0e6f189064a91c5f8eac35bdc303eb56099177207772a06723e47'
  }
};

const delta = Math.round(Math.abs(Number($json.observedScore) - Number($json.baselineScore)) * 1000000) / 1000000;
const passed = delta === 0;
return {
  ...$json,
  tool: {
    id: 'tool:exact-comparator-v1',
    name: 'Exact comparator',
    version: '1.0.0',
    contentDigest: 'sha256:36393db7e722d7040809c53d9a5b1d969a076a332fcc4bae51a52a1b949b32a7'
  },
  comparison: {
    mode: 'exact',
    comparator: 'exact-digest',
    baseline: Number($json.baselineScore),
    observed: Number($json.observedScore),
    delta,
    tolerance: 0,
    passed,
    reasonCode: passed ? 'exact_match' : 'exact_value_changed'
  }
};

const tolerance = Number($json.tolerance);
const delta = Math.round(Math.abs(Number($json.observedScore) - Number($json.baselineScore)) * 1000000) / 1000000;
const passed = delta <= tolerance;
return {
  ...$json,
  tool: {
    id: 'tool:tolerance-comparator-v1',
    name: 'Tolerance comparator',
    version: '1.0.0',
    contentDigest: 'sha256:01a6628819acf60b29f5afc1ebe573cd813e1ba04dc4c38d57f00b2d16a98d6f'
  },
  comparison: {
    mode: 'tolerance',
    comparator: 'numeric-absolute-tolerance',
    baseline: Number($json.baselineScore),
    observed: Number($json.observedScore),
    delta,
    tolerance,
    passed,
    reasonCode: passed ? 'within_tolerance' : 'outside_tolerance'
  }
};

const artifactUri = 'urn:sciforge:artifact:dag-v3-controlled-report:v2';
const contentDigest = 'sha256:40d20ecadee0e7b143c36afe7665e8bb331be9e2a288cbf532cd735230763de1';
const score = Number($json.observedScore);
const comparisonName = `${$json.comparison.comparator}: delta=${$json.comparison.delta}`;
return {
  ...$json,
  artifactUri,
  contentDigest,
  mediaType: 'application/vnd.sciforge.reproducibility+json',
  artifact: {
    id: 'artifact:dag-v3-controlled-report-v2',
    status: 'matched',
    comparison: $json.comparison
  },
  evidenceLineage: {
    evidence: [
      {
        id: 'evidence:dag-v3-controlled-score',
        type: 'finding',
        name: `固定输入产生分数 ${score}`,
        score,
        sampleId: String($json.sampleId)
      },
      {
        id: 'evidence:dag-v3-comparison-match',
        type: 'observation',
        name: comparisonName,
        comparator: $json.comparison.comparator,
        delta: $json.comparison.delta,
        tolerance: $json.comparison.tolerance
      },
      {
        id: 'evidence:dag-v3-controlled-artifact',
        type: 'artifact',
        name: 'DAG v3 确定性比较报告',
        artifact: {
          kind: 'analysis-result',
          locator: artifactUri,
          contentDigest,
          version: '2',
          mediaType: 'application/vnd.sciforge.reproducibility+json',
          retention: 'reference'
        }
      },
      {
        id: 'evidence:dag-v3-environment-lock',
        type: 'observation',
        name: '受控环境与依赖锁已固定',
        environment: $json.environment,
        codeDigest: $json.codeSnapshot.contentDigest
      }
    ],
    conclusions: [
      {
        id: 'conclusion:dag-v3-controlled-rerun',
        name: '该结论可追溯到完整执行证据并可按规范重跑',
        replicationStatus: 'matched'
      },
      {
        id: 'conclusion:dag-v3-evidence-package-complete',
        name: '输入、环境、代码、工具与 Artifact 证据包完整',
        evidenceCount: 4
      }
    ],
    relations: [
      {
        src: 'evidence:dag-v3-controlled-score',
        dst: 'conclusion:dag-v3-controlled-rerun',
        rel: 'supports'
      },
      {
        src: 'evidence:dag-v3-comparison-match',
        dst: 'conclusion:dag-v3-controlled-rerun',
        rel: 'supports'
      },
      {
        src: 'evidence:dag-v3-controlled-artifact',
        dst: 'conclusion:dag-v3-evidence-package-complete',
        rel: 'supports'
      },
      {
        src: 'evidence:dag-v3-environment-lock',
        dst: 'conclusion:dag-v3-evidence-package-complete',
        rel: 'supports'
      },
      {
        src: 'conclusion:dag-v3-evidence-package-complete',
        dst: 'conclusion:dag-v3-controlled-rerun',
        rel: 'prerequisite'
      },
      {
        src: 'evidence:dag-v3-comparison-match',
        dst: 'evidence:dag-v3-controlled-score',
        rel: 'refines'
      },
      {
        src: 'evidence:dag-v3-controlled-artifact',
        dst: 'evidence:dag-v3-comparison-match',
        rel: 'derived_from'
      }
    ]
  }
};

const artifactUri = 'urn:sciforge:artifact:dag-v3-deviation-report:v2';
const contentDigest = 'sha256:07b0a3f215f63fdd13f180f46a5fb6b498d23b1d3c835fafcf36be82f4f4f216';
const score = Number($json.observedScore);
return {
  ...$json,
  artifactUri,
  contentDigest,
  mediaType: 'application/vnd.sciforge.reproducibility+json',
  artifact: {
    id: 'artifact:dag-v3-deviation-report-v2',
    status: 'different',
    comparison: $json.comparison
  },
  evidenceLineage: {
    evidence: [
      {
        id: 'evidence:dag-v3-controlled-score',
        type: 'finding',
        name: `固定输入产生分数 ${score}`,
        score,
        sampleId: String($json.sampleId)
      },
      {
        id: 'evidence:dag-v3-comparison-difference',
        type: 'observation',
        name: `比较差异 delta=${$json.comparison.delta}`,
        comparator: $json.comparison.comparator,
        reasonCode: $json.comparison.reasonCode
      },
      {
        id: 'evidence:dag-v3-deviation-artifact',
        type: 'artifact',
        name: 'DAG v3 可解释差异报告',
        artifact: {
          kind: 'analysis-result',
          locator: artifactUri,
          contentDigest,
          version: '2',
          mediaType: 'application/vnd.sciforge.reproducibility+json',
          retention: 'reference'
        }
      },
      {
        id: 'evidence:dag-v3-environment-lock',
        type: 'observation',
        name: '受控环境与依赖锁已固定',
        environment: $json.environment,
        codeDigest: $json.codeSnapshot.contentDigest
      }
    ],
    conclusions: [
      {
        id: 'conclusion:dag-v3-controlled-difference',
        name: '本次结果与基线存在可解释差异',
        replicationStatus: 'different'
      },
      {
        id: 'conclusion:dag-v3-evidence-review-required',
        name: '证据包完整，但发布前需要复核差异原因',
        evidenceCount: 4
      }
    ],
    relations: [
      {
        src: 'evidence:dag-v3-controlled-score',
        dst: 'conclusion:dag-v3-controlled-difference',
        rel: 'supports'
      },
      {
        src: 'evidence:dag-v3-comparison-difference',
        dst: 'conclusion:dag-v3-controlled-difference',
        rel: 'supports'
      },
      {
        src: 'evidence:dag-v3-deviation-artifact',
        dst: 'conclusion:dag-v3-evidence-review-required',
        rel: 'supports'
      },
      {
        src: 'evidence:dag-v3-environment-lock',
        dst: 'conclusion:dag-v3-evidence-review-required',
        rel: 'supports'
      },
      {
        src: 'conclusion:dag-v3-evidence-review-required',
        dst: 'conclusion:dag-v3-controlled-difference',
        rel: 'prerequisite'
      },
      {
        src: 'evidence:dag-v3-comparison-difference',
        dst: 'evidence:dag-v3-controlled-score',
        rel: 'refines'
      },
      {
        src: 'evidence:dag-v3-deviation-artifact',
        dst: 'evidence:dag-v3-comparison-difference',
        rel: 'derived_from'
      }
    ]
  }
};

const lineage = $json.evidenceLineage ?? {};
const evidence = Array.isArray(lineage.evidence) ? lineage.evidence : [];
const normalizedEvidence = evidence.map((item) => {
  if (item?.type !== 'artifact' || !item.artifact) return item;
  const locator = String(item.artifact.locator ?? '').replace(
    'urn:sciforge:artifact:',
    'runtime:sciforge.create-loop/'
  );
  return {
    ...item,
    artifact: {
      ...item.artifact,
      kind: 'other',
      locator
    }
  };
});
const generatedBy = normalizedEvidence.map((item) => ({
  src: item.id,
  dst: '$execution',
  rel: 'generated_by'
}));
return {
  ...$json,
  evidenceLineage: {
    ...lineage,
    evidence: normalizedEvidence,
    relations: [...(lineage.relations ?? []), ...generatedBy]
  }
};
